#!/usr/bin/env python3
"""IT10 P2.1: writes the hand-authored judgement tables (premises, direction evidence, alternatives, verdicts, hypotheses/measurements) as TSV.
The content is authored by the Scientist from the sources named in each row; the numbers computed by the other scripts of this folder are quoted, not recomputed here.
Usage: python3 -I build_tables_it10_p21.py"""
import csv
from pathlib import Path
HERE = Path(__file__).resolve().parent

def w(name, header, rows):
    for r in rows:
        assert len(r) == len(header), (name, r[0], len(r), len(header))
    with (HERE / name).open("w", newline="", encoding="utf-8") as h:
        c = csv.writer(h, delimiter="\t"); c.writerow(header); c.writerows(rows)

